<?php
declare(strict_types=1);
use DigiForge\AI\{ImageGenerationAccess as Access,ImageGenerationJournal as Journal,ImageGenerationPolicyRepository as Policy};
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/fixtures/ImageGenerationPolicyJournalFixture.php';
final class ImageGenerationPolicyJournalTest extends WP_UnitTestCase {
 private int $actor;private array $policy;private ImageGenerationPolicyJournalFixture $fixture;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->fixture=new ImageGenerationPolicyJournalFixture();$this->fixture->capture();$this->actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($this->actor);ShopAccessFixture::authorizeActor($this->actor,['personalized_pod'],['manage_digiforge_pod','manage_digiforge_ai']);global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$repo=new DigiForge\AI\Repository();$suffix=substr(wp_generate_uuid4(),0,8);$task=$repo->createTask(['task_key'=>'image-'.$suffix,'name'=>'Image','environment'=>'production','required_capabilities'=>['image_generation']]);$model=$repo->createModel(['model_key'=>'image-'.$suffix,'provider'=>'openai','model_class'=>'image','environment'=>'production','capabilities'=>['image_generation'],'enabled'=>true,'fallback_order'=>0]);self::assertIsArray($task);self::assertIsArray($model);$wpdb->query('UPDATE '.DigiForge\Database\Tables::ai_models().' SET enabled=0 WHERE id<>'.(int)$model['id']);$integrations=new DigiForge\Integrations\Repository();$integration=$integrations->create(['provider'=>'ai','environment'=>'production','connection_key'=>'image-'.$suffix,'status'=>'CONFIGURED','enabled'=>false]);self::assertIsArray($integration);self::assertTrue($integrations->storeSecret($integration['id'],'api_key','synthetic-not-a-real-key'));self::assertIsArray($integrations->setEnabled($integration['id'],true));$this->policy=['policy_key'=>'image-'.$suffix,'version'=>'v1','binding'=>['task_id'=>$task['id'],'provider_models'=>[$model['id']=>'gpt-image-1']],'integration_id'=>$integration['id'],'size'=>'1024x1024','quality'=>'low','maximum_task_charge'=>'1.00','currency'=>'USD','timeout_seconds'=>20,'max_output_bytes'=>2097152,'engines'=>['ORIGINAL_ARTWORK'],'prompt_version'=>'v1','terms_source_sha256'=>hash('sha256','synthetic terms')];}
 protected function tearDown():void {try{$this->fixture->restore();}finally{parent::tearDown();}}
 private function identity(string $policyHash):array {$wire=DigiForge\AI\ImageGenerationWireContract::request('gpt-image-1','Synthetic offline image','1024x1024','low',null);unset($wire['body']);return ['version'=>'shop2-image-request-v1','shop_key'=>'personalized_pod','mode'=>'OFFLINE_SIMULATOR','source_type'=>'DESIGN','source_key'=>'synthetic-'.wp_rand(),'source_version'=>hash('sha256','source'),'engine'=>'ORIGINAL_ARTWORK','policy_sha256'=>$policyHash,'run_context'=>['run_id'=>'image-test','started_at'=>gmdate('Y-m-d H:i:s')],'wire_contract'=>$wire,'prompt'=>'Synthetic offline image','source_asset'=>null,'created_by'=>$this->actor];}
 public function testModuleClassesExist():void {self::assertTrue(class_exists(Access::class),'image access gate required');self::assertTrue(class_exists(Policy::class),'image policy repository required');self::assertTrue(class_exists(Journal::class),'image journal required');}
 public function testPolicyReviewReplayDriftAndHistoricalRead():void {$repo=new Policy();$review=$repo->review($this->policy);self::assertIsArray($review);self::assertFalse($review['policy']['enabled']);self::assertSame($review,$repo->review($this->policy));self::assertIsArray($repo->resolve($review['hash']));$changed=$this->policy;$changed['quality']='high';self::assertWPError($repo->review($changed));global $wpdb;$wpdb->update(DigiForge\Database\Tables::ai_tasks(),['name'=>'Drift'],['id'=>$this->policy['binding']['task_id']]);self::assertWPError($repo->resolve($review['hash']));self::assertSame($review,$repo->read($review['hash']));self::assertNotEmpty($repo->recent());}
 public function testJournalCasChainImmutableHistoryAndNoRetry():void {$policy=(new Policy())->review($this->policy);self::assertIsArray($policy);$journal=new Journal();$identity=$this->identity($policy['hash']);$first=$journal->create($identity);self::assertIsArray($first);self::assertSame('PREPARED',$first['state']);self::assertSame($first,$journal->create($identity));$reserved=$journal->append($first['id'],$first['event_sha256'],['state'=>'RESERVED','usage_id'=>12]);self::assertIsArray($reserved);self::assertWPError($journal->append($first['id'],$first['event_sha256'],['state'=>'CANCELLED']));self::assertWPError($journal->append($first['id'],$reserved['event_sha256'],['identity'=>[],'state'=>'DISPATCHING']));$dispatch=$journal->append($first['id'],$reserved['event_sha256'],['state'=>'DISPATCHING','dispatched_at'=>gmdate('Y-m-d H:i:s')]);self::assertIsArray($dispatch);$unknown=$journal->append($first['id'],$dispatch['event_sha256'],['state'=>'UNKNOWN','error_class'=>'transport_unknown']);self::assertIsArray($unknown);self::assertWPError($journal->append($first['id'],$unknown['event_sha256'],['state'=>'RESERVED']));self::assertCount(4,$journal->history($first['id']));self::assertCount(1,$journal->recent($identity['source_key']));global $wpdb;$wpdb->delete($wpdb->options,['option_name'=>'digiforge_image_job_event_'.$first['id'].'_1']);self::assertWPError($journal->read($first['id']));}
 public function testAuthorizationRejectsCallerTransactionsWithoutCommit():void {self::assertTrue(Access::authorize());self::assertFalse(Access::networkAllowed());global $wpdb;$wpdb->query('START TRANSACTION');self::assertWPError(Access::authorize());self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));$wpdb->query('ROLLBACK');$wpdb->query('SET autocommit=0');self::assertWPError(Access::authorize());self::assertSame('0',(string)$wpdb->get_var('SELECT @@session.autocommit'));$wpdb->query('SET autocommit=1');}
 public function testAuthorizationFreshlyDetectsRoleRevocation():void {self::assertTrue(Access::authorize());global $wpdb;$wpdb->update($wpdb->usermeta,['meta_value'=>serialize(['subscriber'=>true])],['user_id'=>$this->actor,'meta_key'=>$wpdb->prefix.'capabilities']);self::assertWPError(Access::authorize());}
 public function testPolicyAndJournalRejectUnboundedOrSecretInputs():void {$repo=new Policy();$bad=$this->policy;$bad['api_key']='forbidden';self::assertWPError($repo->review($bad));$bad=$this->policy;$bad['maximum_task_charge']=0.1;self::assertWPError($repo->review($bad));$policy=$repo->review($this->policy);self::assertIsArray($policy);$identity=$this->identity($policy['hash']);$identity['wire_contract']['body']='forbidden';self::assertWPError((new Journal())->create($identity));}
 public function testJournalRejectsForgedOlderHead():void {$p=(new Policy())->review($this->policy);self::assertIsArray($p);$j=new Journal();$first=$j->create($this->identity($p['hash']));self::assertIsArray($first);self::assertIsArray($j->append($first['id'],$first['event_sha256'],['state'=>'CANCELLED']));global $wpdb;$wpdb->update($wpdb->options,['option_value'=>DigiForge\Orders\Validator::canonicalJson(['revision'=>0,'event_sha256'=>$first['event_sha256']])],['option_name'=>'digiforge_image_job_head_'.$first['id']]);self::assertWPError($j->read($first['id']));}
 public function testMissingAuditAndCredentialRotationFailClosed():void {$r=new Policy();$p=$r->review($this->policy);self::assertIsArray($p);$integrations=new DigiForge\Integrations\Repository();self::assertTrue($integrations->storeSecret($p['policy']['integration_id'],'api_key','synthetic-rotated-not-real'));self::assertWPError($r->resolve($p['hash']));self::assertIsArray($r->read($p['hash']));global $wpdb;$wpdb->delete(DigiForge\Database\Tables::audit_log(),['event_type'=>'image_policy_review','object_id'=>$p['hash']],['%s','%s']);self::assertWPError($r->read($p['hash']));}
 public function testJournalSuccessorRequiresClosedEligibleParent():void {$p=(new Policy())->review($this->policy);self::assertIsArray($p);$j=new Journal();$identity=$this->identity($p['hash']);$first=$j->create($identity);self::assertIsArray($first);$child=$identity;$child['parent_job']=$first['id'];self::assertWPError($j->create($child));$cancelled=$j->append($first['id'],$first['event_sha256'],['state'=>'CANCELLED']);self::assertIsArray($cancelled);$next=$j->create($child);self::assertIsArray($next);self::assertNotSame($first['id'],$next['id']);self::assertCount(2,$j->recent($identity['source_key']));}
 public function testJournalRejectsAbsolutePathsAndCredentialMetadata():void {$p=(new Policy())->review($this->policy);self::assertIsArray($p);$j=new Journal();$identity=$this->identity($p['hash']);$identity['source_asset']=['storage_reference'=>'/tmp/private.png'];self::assertWPError($j->create($identity));$identity['source_asset']=['api_key'=>'forbidden'];self::assertWPError($j->create($identity));}

 public function testAuthorizationFreshlyDetectsStoredRoleCapabilityRevocation():void {self::assertTrue(Access::authorize());global $wpdb;$key=$wpdb->prefix.'user_roles';$roles=get_option($key);$roles['administrator']['capabilities']['manage_digiforge_ai']=false;$wpdb->update($wpdb->options,['option_value'=>serialize($roles)],['option_name'=>$key]);self::assertWPError(Access::authorize());}

 public function testRecentListsOnlyCurrentActorsJobsWithoutDisclosingOtherOperators():void {
  $p=(new Policy())->review($this->policy);self::assertIsArray($p);$journal=new Journal();$identity=$this->identity($p['hash']);$original=$journal->create($identity);self::assertIsArray($original);$other=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($other);ShopAccessFixture::authorizeActor($other,['personalized_pod'],['manage_digiforge_pod','manage_digiforge_ai']);global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$identity['created_by']=$other;$mine=$journal->create($identity);self::assertIsArray($mine);
  $recent=$journal->recent($identity['source_key']);self::assertIsArray($recent,'Another authorized creator must not block this actor from discovering their own image attempts.');self::assertSame([$mine['id']],array_column($recent,'id'));self::assertWPError($journal->read($original['id']));self::assertWPError($journal->history($original['id']));self::assertWPError($journal->append($original['id'],$original['event_sha256'],['state'=>'CANCELLED']));$identity['parent_job']=$original['id'];self::assertWPError($journal->create($identity));
  // Foreign corruption must remain visible as a held source, not be silently ignored.
  $wpdb->delete(DigiForge\Database\Tables::audit_log(),['event_type'=>'image_job_event','object_id'=>$original['id']]);self::assertWPError($journal->recent($identity['source_key']));
 }

}
